+            "coherent multiplier emitted a conditioned or non-gate operation"
+        );
+    }
+    circ.pop_section(&prev);
+
+    CanonicalCoherentMulInverse {
+        count_only: circ.b.count_only,
+        op_start,
+        gate_count,
+        kind_counts,
+        workspace_ids,
+        result_ids: ids(result),
+        a_ids: ids(a),
+        b_ids: ids(b),
